    AdkItem("sm-01m", "أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لاَ إِلَهَ إلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذِهِ اللَّيْلَةِ وَخَيْرَ مَا بَعْدَهَا، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِي هَذِهِ اللَّيْلَةِ وَشَرِّ مَا بَعْدَهَا، رَبِّ أَعُوذُ بِكَ مِنَ الْكَسَلِ وَسُوءِ الْكِبَرِ، رَبِّ أَعُوذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ", 1, "مسلم 2723", "صحيح — رواه مسلم؛ الألباني: صحيح (صحيح أبي داود 5071، صحيح الترمذي 3390)", "مسلم 2723 (حديث ابن مسعود)؛ وأبو داود 5071، والترمذي 3390", "لفظ مسلم هو لفظ المساء حرفيًا، وفي آخره: «وإذا أصبح قال ذلك أيضًا: أصبحنا وأصبح الملك لله». ولفظ الصباح هنا هو لفظ حصن المسلم بإبدال الليلة باليوم.", "", false, false, ""),
    AdkItem("sm-02m", "اللَّهُمَّ بِكَ أَمْسَيْنَا، وَبِكَ أَصْبَحْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ، وَإِلَيْكَ الْمَصِيرُ", 1, "الأدب المفرد 911", "صحيح — الألباني (صحيح الأدب المفرد 911، صحيح أبي داود 5068، صحيح الترمذي 3391)", "الأدب المفرد 911؛ أبو داود 5068؛ الترمذي 3391", "في رواية الترمذي «المصير» في الصباح و«النشور» في المساء، والألباني في هداية الرواة 2326 صحّح العكس، وهو اللفظ المثبت هنا: «النشور» صباحًا و«المصير» مساءً، كما في الأدب المفرد 911.", "", false, false, ""),
    AdkItem("sm-03m", "اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلاَّ أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ لَكَ بِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لاَ يَغْفِرُ الذُّنوبَ إِلاَّ أَنْتَ", 1, "البخاري 6306", "صحيح — رواه البخاري", "البخاري 6306 (سيد الاستغفار، حديث شداد بن أوس)", "", "«ومَن قالها مِنَ النَّهارِ موقِنًا بها، فماتَ مِن يَومِه قَبلَ أن يُمسيَ، فهو مِن أهلِ الجَنَّةِ، ومَن قالها مِنَ اللَّيلِ وهو موقِنٌ بها، فماتَ قَبلَ أن يُصبِحَ، فهو مِن أهلِ الجَنَّةِ» (البخاري 6306)", false, false, ""),
    AdkItem("sm-04m", "اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَالآخِرَةِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ: فِي دِينِي وَدُنْيَايَ وَأَهْلِي، وَمَالِي، اللَّهُمَّ اسْتُرْ عَوْرَاتِي، وَآمِنْ رَوْعَاتِي، اللَّهُمَّ احْفَظْنِي مِنْ بَينِ يَدَيَّ، وَمِنْ خَلْفِي، وَعَنْ يَمِينِي، وَعَنْ شِمَالِي، وَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي", 1, "أبو داود 5074", "صحيح — الألباني (صحيح الترغيب 659، صحيح أبي داود 5074، صحيح ابن ماجه 3135)", "أبو داود 5074؛ ابن ماجه 3871؛ النسائي 5530؛ أحمد 4785 (حديث ابن عمر: «لم يكن رسول الله ﷺ يدع هؤلاء الدعوات حين يمسي وحين يصبح»)", "اللفظ يطابق نص صحيح الترغيب 659 حرفيًا.", "", false, false, ""),
    AdkItem("sm-05m", "اللَّهُمَّ فَاطِرَ السَّمَوَاتِ وَالْأَرْضِ، عَالِمَ الغَيْبِ وَالشَّهَادَةِ، لاَ إِلَهَ إِلاَّ أَنْتَ، رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي، وَمِنْ شَرِّ الشَّيْطانِ وَشَرَكِهِ، وَأَنْ أَقْتَرِفَ عَلَى نَفْسِي سُوءاً، أَوْ أَجُرَّهُ إِلَى مُسْلِمٍ", 1, "الترمذي 3529", "صحيح — الألباني (صحيح الترمذي 3529، صحيح الأدب المفرد 914)", "الترمذي 3529 (حديث عبد الله بن عمرو: أبو بكر الصديق قال: «علّمني ما أقول إذا أصبحت وإذا أمسيت»)", "", "", false, false, ""),
    AdkItem("sm-06m", "بِسْمِ اللَّهِ الَّذِي لاَ يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلاَ فِي السّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ", 3, "أبو داود 5088", "صحيح — الألباني (صحيح أبي داود 5088، صحيح ابن ماجه 3134، صحيح الجامع 5745)", "أبو داود 5088؛ ابن ماجه (صحيح ابن ماجه 3134) (حديث عثمان بن عفان)", "", "«ما من عبدٍ يقولُ في صباحِ كلِّ يومٍ ومساءِ كلِّ ليلةٍ: بسمِ اللهِ الذي لا يضرُّ مع اسمِه شيءٌ في الأرضِ ولا في السماءِ وهو السميعُ العليمُ، ثلاثَ مراتٍ، فيضرُّه شيءٌ» (صحيح ابن ماجه 3134)", false, false, ""),
    AdkItem("sm-08m", "سُبْحَانَ اللَّهِ وَبِحَمْدِهِ", 100, "مسلم 2692", "صحيح — رواه مسلم", "مسلم 2692 (حديث أبي هريرة)", "", "«مَن قال حينَ يُصبِحُ وحينَ يُمسي: سُبحانَ اللهِ وبحَمدِه، مِائةَ مَرَّةٍ، لم يَأتِ أحَدٌ يَومَ القيامةِ بأفضَلَ ممَّا جاءَ به، إلَّا أحَدٌ قال مِثلَ ما قال، أو زادَ عليه» (مسلم 2692)", false, false, ""),
    AdkItem("sm-09m", "لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ", 1, "أبو داود 5077", "صحيح — الألباني (صحيح أبي داود 5077، صحيح الترغيب 656، صحيح الجامع 6418)", "أبو داود 5077؛ ابن ماجه 3867؛ أحمد 16583 (حديث أبي عياش)", "العدد مرة واحدة كما في أبي داود 5077 (صحيح). رواية «عشر مرات إذا أصبح» حكم عليها الألباني بـ«حسن صحيح» (صحيح الترغيب 474)، وفي إسنادها راوٍ لم يوثقه إلا ابن حبان (شعيب)، فلم نعتمد العشر.", "«كان له عدلُ رقبةٍ مِن ولدِ إسماعيلَ، وكتب له عشرَ حسناتٍ، وحطَّ عنه عشرَ سيئاتٍ، ورفع له عشرَ درجاتٍ، وكان في حِرْزٍ مِن الشيطانِ حتى يُمسي. وإن قالها إذا أمسى كان له مثلُ ذلك حينَ يُصبحُ» (أبو داود 5077)", false, false, ""),
    AdkItem("sm-13m", "أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ", 3, "الترمذي 3604", "صحيح — الألباني (صحيح الترمذي 3604، صحيح الترغيب 652، صحيح الجامع 6427)", "الترمذي 3604 (حديث أبي هريرة)؛ وأصله في مسلم 2709 مختصرًا", "", "«لم يضُرَّهُ حُمةٌ تلكَ اللَّيلةَ» (الترمذي 3604)", false, false, "")
