    AdkItem("as-07", "اللَّهُ أَكْبَرُ", 33, "مسلم 597", "صحيح — رواه مسلم؛ الألباني: صحيح (صحيح الجامع 6286)", "مسلم 597 (حديث أبي هريرة): «من سبّح الله في دبر كل صلاة ثلاثًا وثلاثين، وحمد الله ثلاثًا وثلاثين، وكبّر الله ثلاثًا وثلاثين... وقال تمام المئة»", "الصيغة البديلة (مسلم 596): يكبّر 34 ولا يقول تمام المئة. كلتاهما صحيحة، ولا يُجمع بينهما. ألفاظ «سبحان الله، والحمد لله، والله أكبر» بنصها في البخاري 843 ومسلم 595. صيغة ثانية صحيحة: التكبير أربعًا وثلاثين، بدل ثلاث وثلاثين + تمام المئة", "", false, false, ""),
    AdkItem("as-08", "لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ", 1, "مسلم 597", "صحيح — رواه مسلم؛ الألباني: صحيح (صحيح الجامع 6286)", "مسلم 597 (حديث أبي هريرة): «من سبّح الله في دبر كل صلاة ثلاثًا وثلاثين، وحمد الله ثلاثًا وثلاثين، وكبّر الله ثلاثًا وثلاثين... وقال تمام المئة»", "«تمام المئة» بعد التسبيح والتحميد والتكبير 33 مرة. لا يقال مع صيغة التكبير 34.", "«غُفِرَتْ خَطَايَاهُ وَإِنْ كَانَتْ مِثْلَ زَبَدِ الْبَحْرِ» (مسلم 597)", false, false, ""),
    AdkItem("as-09", "قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ ﴿١﴾ مِن شَرِّ مَا خَلَقَ ﴿٢﴾ وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ ﴿٣﴾ وَمِن شَرِّ ٱلنَّفَّـٰثَـٰتِ فِى ٱلْعُقَدِ ﴿٤﴾ وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ ﴿٥﴾", 1, "الفلق: 1–5", "صحيح — الألباني (صحيح أبي داود 1523، صحيح الترمذي 2903)؛ شعيب الأرناؤوط: صحيح (تخريج المسند 17417، تخريج زاد المعاد 1/294)", "أبو داود 1523، والترمذي 2903، والنسائي 1336 (حديث عقبة بن عامر): «أمرني رسول الله ﷺ أن أقرأ بالمعوذات دبر كل صلاة» (ولفظ الترمذي: بالمعوذتين)", "مرة واحدة بعد كل صلاة. سورة الإخلاص ليست هنا: لفظ الترمذي «بالمعوذتين»، ودخول الإخلاص في «المعوذات» اجتهاد من بعض الشراح (انظر قائمة المختلف فيه). البسملة تُقرأ في أول السورة ولا تُعدّ من آياتها.", "", true, true, ""),
    AdkItem("as-10", "قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ ﴿١﴾ مَلِكِ ٱلنَّاسِ ﴿٢﴾ إِلَـٰهِ ٱلنَّاسِ ﴿٣﴾ مِن شَرِّ ٱلْوَسْوَاسِ ٱلْخَنَّاسِ ﴿٤﴾ ٱلَّذِى يُوَسْوِسُ فِى صُدُورِ ٱلنَّاسِ ﴿٥﴾ مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ ﴿٦﴾", 1, "الناس: 1–6", "صحيح — الألباني (صحيح أبي داود 1523، صحيح الترمذي 2903)؛ شعيب الأرناؤوط: صحيح (تخريج المسند 17417، تخريج زاد المعاد 1/294)", "أبو داود 1523، والترمذي 2903، والنسائي 1336 (حديث عقبة بن عامر): «أمرني رسول الله ﷺ أن أقرأ بالمعوذات دبر كل صلاة» (ولفظ الترمذي: بالمعوذتين)", "مرة واحدة بعد كل صلاة. سورة الإخلاص ليست هنا: لفظ الترمذي «بالمعوذتين»، ودخول الإخلاص في «المعوذات» اجتهاد من بعض الشراح (انظر قائمة المختلف فيه). البسملة تُقرأ في أول السورة ولا تُعدّ من آياتها.", "", true, true, ""),
    AdkItem("as-12", "اللَّهُمَّ أَعِنِّي عَلَى ذِكْرِكَ، وَشُكْرِكَ، وَحُسْنِ عِبَادَتِكَ", 1, "أبو داود 1522", "صحيح — الألباني (صحيح أبي داود 1522، صحيح النسائي 1302)؛ النووي: إسناده صحيح (الأذكار 103، رياض الصالحين 183)؛ ابن حجر: صحيح (نتائج الأفكار 2/297)؛ شعيب الأرناؤوط: إسناده صحيح (تخريج المسند 22119)", "أبو داود 1522، والنسائي 1303، وأحمد 22119 (حديث معاذ بن جبل): «أوصيك يا معاذ لا تدعنّ في دبر كل صلاة تقول: اللهم أعني على ذكرك وشكرك وحسن عبادتك»", "في رواية النسائي «رب أعني»، وأثبتنا لفظ أبي داود «اللهم أعني».", "", false, false, ""),
    AdkItem("as-13", "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْجُبْنِ، وَأَعُوذُ بِكَ أَنْ أُرَدَّ إِلَى أَرْذَلِ الْعُمُرِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الدُّنْيَا، وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ", 1, "البخاري 2822", "صحيح — رواه البخاري", "البخاري 2822 (سعد بن أبي وقاص): «إن رسول الله ﷺ كان يتعوذ منهن دبر الصلاة»", "", "", false, false, "")
    )
    val nawm: List<AdkItem> = listOf(
    AdkItem("sl-q1", "قُلْ هُوَ ٱللَّهُ أَحَدٌ ﴿١﴾ ٱللَّهُ ٱلصَّمَدُ ﴿٢﴾ لَمْ يَلِدْ وَلَمْ يُولَدْ ﴿٣﴾ وَلَمْ يَكُن لَّهُۥ كُفُوًا أَحَدٌۢ ﴿٤﴾", 3, "الإخلاص: 1–4", "صحيح — رواه البخاري؛ الألباني: صحيح (صحيح الترمذي 3402)", "البخاري 5017 (حديث عائشة): «كان إذا أوى إلى فراشه كل ليلة جمع كفيه ثم نفث فيهما فقرأ فيهما: قل هو الله أحد، وقل أعوذ برب الفلق، وقل أعوذ برب الناس، ثم يمسح بهما ما استطاع من جسده، يبدأ بهما على رأسه ووجهه وما أقبل من جسده، يفعل ذلك ثلاث مرات»", "الصفة: يجمع كفيه وينفث فيهما ويقرأ السور الثلاث، ثم يمسح بهما ما استطاع من جسده مبتدئًا برأسه ووجهه وما أقبل من جسده — ويفعل ذلك كله ثلاث مرات. العدد 3 للسور الثلاث معًا.", "", true, true, ""),
    AdkItem("sl-q2", "قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ ﴿١﴾ مِن شَرِّ مَا خَلَقَ ﴿٢﴾ وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ ﴿٣﴾ وَمِن شَرِّ ٱلنَّفَّـٰثَـٰتِ فِى ٱلْعُقَدِ ﴿٤﴾ وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ ﴿٥﴾", 3, "الفلق: 1–5", "صحيح — رواه البخاري؛ الألباني: صحيح (صحيح الترمذي 3402)", "البخاري 5017 (حديث عائشة): «كان إذا أوى إلى فراشه كل ليلة جمع كفيه ثم نفث فيهما فقرأ فيهما: قل هو الله أحد، وقل أعوذ برب الفلق، وقل أعوذ برب الناس، ثم يمسح بهما ما استطاع من جسده، يبدأ بهما على رأسه ووجهه وما أقبل من جسده، يفعل ذلك ثلاث مرات»", "الصفة: يجمع كفيه وينفث فيهما ويقرأ السور الثلاث، ثم يمسح بهما ما استطاع من جسده مبتدئًا برأسه ووجهه وما أقبل من جسده — ويفعل ذلك كله ثلاث مرات. العدد 3 للسور الثلاث معًا.", "", true, true, ""),
