    AdkItem("sl-04", "ٱللَّهُ لَآ إِلَـٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ ۚ لَا تَأْخُذُهُۥ سِنَةٌ وَلَا نَوْمٌ ۚ لَّهُۥ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ مَن ذَا ٱلَّذِى يَشْفَعُ عِندَهُۥٓ إِلَّا بِإِذْنِهِۦ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَىْءٍ مِّنْ عِلْمِهِۦٓ إِلَّا بِمَا شَآءَ ۚ وَسِعَ كُرْسِيُّهُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ ۖ وَلَا يَـُٔودُهُۥ حِفْظُهُمَا ۚ وَهُوَ ٱلْعَلِىُّ ٱلْعَظِيمُ ﴿٢٥٥﴾", 1, "البقرة: 255", "صحيح — البخاري؛ الألباني: صحيح (صحيح الترغيب 610)", "البخاري 2311 (تعليقًا مجزومًا به) و3275 (حديث أبي هريرة في حفظ زكاة رمضان): «إذا أويت إلى فراشك فاقرأ آية الكرسي... حتى تختم الآية»، وقال النبي ﷺ: «صدقك وهو كذوب»", "", "«فَإِنَّكَ لَنْ يَزَالَ عَلَيْكَ مِنَ اللَّهِ حَافِظٌ وَلاَ يَقْرَبَنَّكَ شَيْطَانٌ حَتَّى تُصْبِحَ» (البخاري 2311، وأقرّه النبي ﷺ بقوله: «صدقك وهو كذوب»)", false, true, ""),
    AdkItem("sl-05", "ءَامَنَ ٱلرَّسُولُ بِمَآ أُنزِلَ إِلَيْهِ مِن رَّبِّهِۦ وَٱلْمُؤْمِنُونَ ۚ كُلٌّ ءَامَنَ بِٱللَّهِ وَمَلَـٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِۦ ۚ وَقَالُوا۟ سَمِعْنَا وَأَطَعْنَا ۖ غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ ٱلْمَصِيرُ ﴿٢٨٥﴾ لَا يُكَلِّفُ ٱللَّهُ نَفْسًا إِلَّا وُسْعَهَا ۚ لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا ٱكْتَسَبَتْ ۗ رَبَّنَا لَا تُؤَاخِذْنَآ إِن نَّسِينَآ أَوْ أَخْطَأْنَا ۚ رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَآ إِصْرًا كَمَا حَمَلْتَهُۥ عَلَى ٱلَّذِينَ مِن قَبْلِنَا ۚ رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِۦ ۖ وَٱعْفُ عَنَّا وَٱغْفِرْ لَنَا وَٱرْحَمْنَآ ۚ أَنتَ مَوْلَىٰنَا فَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَـٰفِرِينَ ﴿٢٨٦﴾", 1, "البقرة: 285–286", "صحيح — متفق عليه", "البخاري 5009 و5008 و5051، ومسلم 807 و808 (حديث أبي مسعود البدري): «من قرأ بالآيتين من آخر سورة البقرة في ليلة كفتاه»", "", "«مَنْ قَرَأَ بِالآيَتَيْنِ مِنْ آخِرِ سُورَةِ الْبَقَرَةِ فِي لَيْلَةٍ كَفَتَاهُ» (البخاري 5009)", false, true, ""),
    AdkItem("sl-06", "بِاسْمِكَ رَبِّ وَضَعْتُ جَنْبِي، وَبِكَ أَرْفَعُهُ، إِنْ أَمْسَكْتَ نَفْسِي فَارْحَمْهَا، وَإِنْ أَرْسَلْتَهَا فَاحْفَظْهَا بِمَا تَحْفَظُ بِهِ عِبَادَكَ الصَّالِحِينَ", 1, "البخاري 6320", "صحيح — رواه البخاري", "البخاري 6320 (حديث أبي هريرة): «إذا أوى أحدكم إلى فراشه فلينفض فراشه بداخلة إزاره... ثم يقول»", "السنة قبله: نفض الفراش بداخلة الإزار، والاضطجاع على الشق الأيمن.", "", false, false, ""),
    AdkItem("sl-07", "اللَّهُمَّ خَلَقْتَ نَفْسِي وَأَنْتَ تَوَفَّاهَا، لَكَ مَمَاتُهَا وَمَحْيَاهَا، إِنْ أَحْيَيْتَهَا فَاحْفَظْهَا، وَإِنْ أَمَتَّهَا فَاغْفِرْ لَهَا، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَافِيَةَ", 1, "مسلم 2712", "صحيح — رواه مسلم", "مسلم 2712 (حديث عبد الله بن عمر): «أنه أمر رجلًا إذا أخذ مضجعه قال...»، فقال له رجل: أسمعت هذا من عمر؟ فقال: من خير من عمر، من رسول الله ﷺ", "", "", false, false, ""),
    AdkItem("sl-08", "اللَّهُمَّ قِنِي عَذَابَكَ يَوْمَ تَبْعَثُ عِبَادَكَ", 1, "أبو داود 5045", "صحيح دون قوله «ثلاث مرار» — الألباني (صحيح أبي داود 5045)؛ ابن حجر: حسن (نتائج الأفكار 3/51)", "أبو داود 5045 (حديث حفصة): «كان إذا أراد أن يرقد وضع يده اليمنى تحت خده ثم يقول...»؛ ونحوه الترمذي 3398 (حديث حذيفة: «يوم تجمع - أو تبعث - عبادك»)", "العدد مرة واحدة: زيادة «ثلاث مرار» في رواية أبي داود حكم الألباني بعدم صحتها. السنة: وضع اليد اليمنى تحت الخد.", "", false, false, ""),
    AdkItem("sl-09", "بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا", 1, "البخاري 6324", "صحيح — رواه البخاري", "البخاري 6324 (حديث حذيفة)؛ ونحوه البخاري 6314", "", "", false, false, ""),
    AdkItem("sl-10", "سُبْحَانَ اللَّهِ", 33, "البخاري 5361", "صحيح — متفق عليه", "البخاري 5361 و3705، ومسلم 2727 (حديث علي في قصة فاطمة لما سألت خادمًا): «إذا أخذتما مضاجعكما فسبّحا ثلاثًا وثلاثين، واحمدا ثلاثًا وثلاثين، وكبّرا أربعًا وثلاثين، فهو خير لكما من خادم»", "", "", false, false, ""),
    AdkItem("sl-11", "الْحَمْدُ لِلَّهِ", 33, "البخاري 5361", "صحيح — متفق عليه", "البخاري 5361 و3705، ومسلم 2727 (حديث علي في قصة فاطمة لما سألت خادمًا): «إذا أخذتما مضاجعكما فسبّحا ثلاثًا وثلاثين، واحمدا ثلاثًا وثلاثين، وكبّرا أربعًا وثلاثين، فهو خير لكما من خادم»", "", "", false, false, ""),
    AdkItem("sl-12", "اللَّهُ أَكْبَرُ", 34, "البخاري 5361", "صحيح — متفق عليه", "البخاري 5361 و3705، ومسلم 2727 (حديث علي في قصة فاطمة لما سألت خادمًا): «إذا أخذتما مضاجعكما فسبّحا ثلاثًا وثلاثين، واحمدا ثلاثًا وثلاثين، وكبّرا أربعًا وثلاثين، فهو خير لكما من خادم»", "في البخاري 5361 الترتيب: تسبيح ثم تحميد ثم تكبير، وفي 3705 ومسلم 2727 قُدّم التكبير. كله صحيح.", "«فَهُوَ خَيْرٌ لَكُمَا مِنْ خَادِمٍ» (البخاري 5361)", false, false, ""),
    AdkItem("sl-13", "اللَّهُمَّ رَبَّ السَّمَوَاتِ وَرَبَّ الْأَرْضِ وَرَبَّ الْعَرْشِ الْعَظِيمِ، رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ، فَالِقَ الْحَبِّ وَالنَّوَى، وَمُنْزِلَ التَّوْرَاةِ وَالْإِنْجِيلِ وَالْفُرْقَانِ، أَعُوذُ بِكَ مِنْ شَرِّ كُلِّ شَيْءٍ أَنْتَ آخِذٌ بِنَاصِيَتِهِ، اللَّهُمَّ أَنْتَ الْأَوَّلُ فَلَيْسَ قَبْلَكَ شَيْءٌ، وَأَنْتَ الْآخِرُ فَلَيْسَ بَعْدَكَ شَيْءٌ، وَأَنْتَ الظَّاهِرُ فَلَيْسَ فَوْقَكَ شَيْءٌ، وَأَنْتَ الْبَاطِنُ فَلَيْسَ دُونَكَ شَيْءٌ، اقْضِ عَنَّا الدَّيْنَ، وَأَغْنِنَا مِنَ الْفَقْرِ", 1, "مسلم 2713", "صحيح — رواه مسلم", "مسلم 2713 (حديث أبي هريرة): «كان يأمرنا إذا أخذ أحدنا مضجعه أن يقول...»", "السنة: الاضطجاع على الشق الأيمن.", "", false, false, ""),
    AdkItem("sl-14", "الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنَا وَسَقَانَا، وَكَفَانَا، وَآوَانَا، فَكَمْ مِمَّنْ لاَ كَافِيَ لَهُ وَلاَ مُؤْوِيَ", 1, "مسلم 2715", "صحيح — رواه مسلم", "مسلم 2715 (حديث أنس): «كان إذا أوى إلى فراشه قال...»", "", "", false, false, ""),
    AdkItem("sl-15", "اللَّهُمَّ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ، فَاطِرَ السَّمَوَاتِ وَالْأَرْضِ، رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ، أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ أَنْتَ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي، وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ", 1, "الترمذي 3392", "صحيح — الألباني (صحيح الترمذي 3392، صحيح أبي داود 5067)", "الترمذي 3392، وأبو داود 5067 (حديث أبي هريرة: أن أبا بكر قال: علّمني شيئًا أقوله إذا أصبحت وإذا أمسيت، فقال: «قل...»، وفيه: «قله إذا أصبحت وإذا أمسيت وإذا أخذت مضجعك»)", "", "", false, false, ""),
    AdkItem("sl-16", "اللَّهُمَّ أَسْلَمْتُ نَفْسِي إِلَيْكَ، وَفَوَّضْتُ أَمْرِي إِلَيْكَ، وَوَجَّهْتُ وَجْهِي إِلَيْكَ، وَأَلْجَأْتُ ظَهْرِي إِلَيْكَ، رَغْبَةً وَرَهْبَةً إِلَيْكَ، لاَ مَلْجَأَ وَلاَ مَنْجَا مِنْكَ إِلاَّ إِلَيْكَ، آمَنْتُ بِكِتَابِكَ الَّذِي أَنْزَلْتَ، وَبِنَبِيِّكَ الَّذِي أَرْسَلْتَ", 1, "البخاري 6313", "صحيح — متفق عليه", "البخاري 6313 (حديث البراء بن عازب)؛ ونحوه البخاري 247 و6315، ومسلم 2710", "اجعله آخر ما تقول قبل النوم: في البخاري 247 «واجعلهن آخر ما تتكلم به»، ومعه: الوضوء والاضطجاع على الشق الأيمن. ولا تُبدَّل «وبنبيك» بـ«وبرسولك» (البخاري 247).", "«فَإِنْ مُتَّ مُتَّ عَلَى الْفِطْرَةِ» (البخاري 6313)", false, false, "")
    )
}
